/**
 * Stream tubes through a 3D vector field on a grid: streamlines integrated from starting points, drawn as lit tubes colored by the vector norm, with the radius following the divergence.
 */
export type StreamtubeTrace = Omit<CommonTraceAttributes, 'hoverinfo'> & {
  /**
   * Trace type.
   */
  type: 'streamtube';
  /**
   * Which fields hover labels show: the sample's position (`x`, `y`, `z`), the field's vector there (`u`, `v`, `w`), its `norm`, the `divergence`, `text` and the trace `name`; `'skip'` also turns hover events off.
   *
   * @defaultValue `"x+y+z+norm+text+name"`
   */
  hoverinfo?:
    | 'x'
    | 'y'
    | 'z'
    | 'u'
    | 'v'
    | 'w'
    | 'norm'
    | 'divergence'
    | 'text'
    | 'name'
    | `${'x' | 'y' | 'z' | 'u' | 'v' | 'w' | 'norm' | 'divergence' | 'text' | 'name'}+${string}`
    | 'all'
    | 'none'
    | 'skip';
  /**
   * The 3D scene this trace is drawn in: `'scene'` (`layout.scene`), `'scene2'` (`layout.scene2`), ….
   *
   * @defaultValue `"scene"`
   */
  scene?: 'scene' | `scene${number}`;
  /**
   * X coordinates of the grid nodes (numbers, dates or categories). `x`, `y` and `z` list every node of a rectilinear grid (uniform or not), one axis varying fastest (any order), each axis ascending or descending; other point sets draw nothing, as in Plotly.
   */
  x?: DataColumn;
  /**
   * Y coordinates of the vector field's grid nodes (numbers, dates or categories), flattened: see `x`.
   */
  y?: DataColumn;
  /**
   * Z coordinates of the vector field's grid nodes (numbers, dates or categories), flattened: see `x`.
   */
  z?: DataColumn;
  /**
   * x component of the vector field at each grid node (numbers).
   */
  u?: DataColumn;
  /**
   * y component of the vector field at each grid node (numbers).
   */
  v?: DataColumn;
  /**
   * z component of the vector field at each grid node (numbers).
   */
  w?: DataColumn;
  /**
   * Where the tubes start. Default: the x–z plane at the lowest y of the grid, at every x and z node but the first and last.
   */
  starts?: StreamtubeTraceStarts;
  /**
   * The most samples (segments + 1) per tube. Tubes are sampled every 10 / `maxdisplayed` of the field’s diagonal, so this also sets the sampling step.
   *
   * Minimum: 0
   *
   * @defaultValue `1000`
   */
  maxdisplayed?: number;
  /**
   * Scale of the tube radii. At the default 1, the tubes of adjacent starts touch where the divergence is largest.
   *
   * Minimum: 0
   *
   * @defaultValue `1`
   */
  sizeref?: number;
  /**
   * Text shown in every hover label of the trace (a single string).
   *
   * @defaultValue `""`
   */
  text?: string;
  /**
   * Colorscale for numeric `u/v/w norm` values: a name (`'Viridis'`, `'RdBu'`, …), a list of colors, or `[position, color]` stops from 0 to 1.
   */
  colorscale?: ColorScale | readonly string[] | readonly (readonly (number | string)[])[];
  /**
   * Pick the colorscale from the sign of the color domain (Reds for ≥ 0, Blues for ≤ 0, RdBu across 0). Defaults to true unless `colorscale` is given.
   */
  autocolorscale?: boolean;
  /**
   * Reverse the colorscale (the lowest value gets the last color).
   *
   * @defaultValue `false`
   */
  reversescale?: boolean;
  /**
   * Compute the color domain from the numeric `u/v/w norm` values. Defaults to false when both `cmin` and `cmax` are given.
   */
  cauto?: boolean;
  /**
   * Value mapped to the first colorscale color (with `cmax`; turns `cauto` off).
   */
  cmin?: number;
  /**
   * Value mapped to the last colorscale color (with `cmin`; turns `cauto` off).
   */
  cmax?: number;
  /**
   * With `cauto`, widen the automatic domain so it is symmetric around this value (diverging data).
   */
  cmid?: number;
  /**
   * Show a colorbar for this colorscale (drawn by the colorbar component, plan E5.3).
   *
   * @defaultValue `true`
   */
  showscale?: boolean;
  /**
   * The colorbar of this colorscale (plan E5.3).
   */
  colorbar?: Colorbar;
  /**
   * Share a colorscale and domain with other traces through `layout.coloraxis` (`'coloraxis'`, `'coloraxis2'`, …). Overrides this container's colorscale attributes.
   *
   * @defaultValue `"coloraxis"`
   */
  coloraxis?: 'coloraxis' | `coloraxis${number}`;
  /**
   * Plotly's lighting model: coefficients of the ambient, diffuse and specular light. With `scene.lighting`, they scale the scene's lights.
   */
  lighting?: StreamtubeTraceLighting;
  /**
   * Position of the light (Plotly's model, without `scene.lighting`), in clip space: it moves with the view.
   */
  lightposition?: StreamtubeTraceLightposition;
  /**
   * The material of the surface (Holochart extension). Plotly figures keep the default, `plotly`.
   */
  material?: Bar3dTraceMaterial;
  /**
   * d3 number format of x values in hover labels. Default: the scene's x axis format.
   *
   * @defaultValue `""`
   */
  xhoverformat?: string;
  /**
   * d3 number format of y values in hover labels. Default: the scene's y axis format.
   *
   * @defaultValue `""`
   */
  yhoverformat?: string;
  /**
   * d3 number format of z values in hover labels. Default: the scene's z axis format.
   *
   * @defaultValue `""`
   */
  zhoverformat?: string;
  /**
   * d3 number format of u values in hover labels. Default: the scene's x axis format.
   *
   * @defaultValue `""`
   */
  uhoverformat?: string;
  /**
   * d3 number format of v values in hover labels. Default: the scene's y axis format.
   *
   * @defaultValue `""`
   */
  vhoverformat?: string;
  /**
   * d3 number format of w values in hover labels. Default: the scene's z axis format.
   *
   * @defaultValue `""`
   */
  whoverformat?: string;
};

/**
 * Where the tubes start. Default: the x–z plane at the lowest y of the grid, at every x and z node but the first and last.
 */
export interface StreamtubeTraceStarts {
  /**
   * x coordinates of the tubes' starting positions.
   */
  x?: DataColumn;
  /**
   * y coordinates of the tubes' starting positions.
   */
  y?: DataColumn;
  /**
   * z coordinates of the tubes' starting positions.
   */
  z?: DataColumn;
}

/**
 * Plotly's lighting model: coefficients of the ambient, diffuse and specular light. With `scene.lighting`, they scale the scene's lights.
 */
export interface StreamtubeTraceLighting {
  /**
   * Ambient light: the share of the color shown whatever the direction of the light.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.8`
   */
  ambient?: number;
  /**
   * Diffuse light: the share of the color lit by the light (Lambert).
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.8`
   */
  diffuse?: number;
  /**
   * Specular highlights: the light reflected toward the eye.
   *
   * Range: 0 – 2
   *
   * @defaultValue `0.05`
   */
  specular?: number;
  /**
   * Roughness of the surface: the spread of the specular highlights.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.5`
   */
  roughness?: number;
  /**
   * Fresnel reflection: how much more light surfaces reflect at grazing angles.
   *
   * Range: 0 – 5
   *
   * @defaultValue `0.2`
   */
  fresnel?: number;
  /**
   * Vertex normals ignore triangle normals shorter than this (tiny triangles do not skew smooth shading).
   *
   * Range: 0 – 1
   *
   * @defaultValue `1e-12`
   */
  vertexnormalsepsilon?: number;
  /**
   * Triangles whose normal is shorter than this get no normal in flat shading (degenerate triangles).
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.000001`
   */
  facenormalsepsilon?: number;
}

/**
 * Position of the light (Plotly's model, without `scene.lighting`), in clip space: it moves with the view.
 */
export interface StreamtubeTraceLightposition {
  /**
   * x of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `100000`
   */
  x?: number;
  /**
   * y of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `100000`
   */
  y?: number;
  /**
   * z of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `0`
   */
  z?: number;
}

/**
 * Surface: a grid of heights drawn as a lit 3D surface, built on the GPU from a height texture, with contour lines, projections and an optional wireframe.
 */
export type SurfaceTrace = Omit<CommonTraceAttributes, 'hovertext'> & {
  /**
   * Trace type.
   */
  type: 'surface';
  /**
   * Hover text per point (a 2D array like `z`, or one string); takes precedence over `text`.
   */
  hovertext?: DataColumn;
  /**
   * The 3D scene this trace is drawn in: `'scene'` (`layout.scene`), `'scene2'` (`layout.scene2`), ….
   *
   * @defaultValue `"scene"`
   */
  scene?: 'scene' | `scene${number}`;
  /**
   * Heights: a 2D array, `z[row][column]` (rows along y, columns along x). Non-numeric entries are gaps (see `connectgaps`).
   */
  z?: DataColumn;
  /**
   * x coordinates (numbers, dates or categories): one per column of `z`, or a 2D array like `z` (one per point, for grids that are not rectangular in x and y). Default: the column indices.
   */
  x?: DataColumn;
  /**
   * y coordinates: one per row of `z`, or a 2D array like `z`. Default: the row indices.
   */
  y?: DataColumn;
  /**
   * Values the colorscale colors the surface by, a 2D array like `z`. Default: `z` itself.
   */
  surfacecolor?: DataColumn;
  /**
   * Text per point (a 2D array like `z`, or one string): shown in hover labels and as `%{text}`.
   */
  text?: DataColumn;
  /**
   * Fill the gaps in `z` by interpolating their neighbours (Plotly's Laplace fill) instead of leaving holes.
   *
   * @defaultValue `false`
   */
  connectgaps?: boolean;
  /**
   * Hide the surface itself, keeping its contour lines and wireframe.
   *
   * @defaultValue `false`
   */
  hidesurface?: boolean;
  /**
   * Opacity by color value, like a colorscale: `[[0, 0.1], [0.5, 1], [1, 0.4]]` (positions 0–1 of the color domain, opacities 0–1), or `'max'` (the highest values opaque, the lowest faded to 0.1), `'min'` (the reverse) or `'extremes'` (both ends opaque, the middle faded).
   */
  opacityscale?: unknown;
  /**
   * Colorscale for numeric `z or surfacecolor` values: a name (`'Viridis'`, `'RdBu'`, …), a list of colors, or `[position, color]` stops from 0 to 1.
   */
  colorscale?: ColorScale | readonly string[] | readonly (readonly (number | string)[])[];
  /**
   * Pick the colorscale from the sign of the color domain (Reds for ≥ 0, Blues for ≤ 0, RdBu across 0). Defaults to true unless `colorscale` is given.
   */
  autocolorscale?: boolean;
  /**
   * Reverse the colorscale (the lowest value gets the last color).
   *
   * @defaultValue `false`
   */
  reversescale?: boolean;
  /**
   * Compute the color domain from the numeric `z or surfacecolor` values. Defaults to false when both `cmin` and `cmax` are given.
   */
  cauto?: boolean;
  /**
   * Value mapped to the first colorscale color (with `cmax`; turns `cauto` off).
   */
  cmin?: number;
  /**
   * Value mapped to the last colorscale color (with `cmin`; turns `cauto` off).
   */
  cmax?: number;
  /**
   * With `cauto`, widen the automatic domain so it is symmetric around this value (diverging data).
   */
  cmid?: number;
  /**
   * Show a colorbar for this colorscale (drawn by the colorbar component, plan E5.3).
   *
   * @defaultValue `true`
   */
  showscale?: boolean;
  /**
   * The colorbar of this colorscale (plan E5.3).
   */
  colorbar?: Colorbar;
  /**
   * Share a colorscale and domain with other traces through `layout.coloraxis` (`'coloraxis'`, `'coloraxis2'`, …). Overrides this container's colorscale attributes.
   *
   * @defaultValue `"coloraxis"`
   */
  coloraxis?: 'coloraxis' | `coloraxis${number}`;
  /**
   * Contour lines of constant x, y and z.
   */
  contours?: SurfaceTraceContours;
  /**
   * Plotly's lighting model: coefficients of the ambient, diffuse and specular light. With `scene.lighting`, they scale the scene's lights.
   */
  lighting?: SurfaceTraceLighting;
  /**
   * Position of the light (Plotly's model, without `scene.lighting`), in clip space: it moves with the view.
   */
  lightposition?: SurfaceTraceLightposition;
  /**
   * The material of the surface (Holochart extension). Plotly figures keep the default, `plotly`.
   */
  material?: Bar3dTraceMaterial;
  /**
   * A wireframe over the surface: its grid lines, drawn in the shader (Holochart extension, not in Plotly).
   */
  wireframe?: SurfaceTraceWireframe;
  /**
   * d3 number or date format of x values in hover labels. Default: the axis format.
   *
   * @defaultValue `""`
   */
  xhoverformat?: string;
  /**
   * d3 number or date format of y values in hover labels. Default: the axis format.
   *
   * @defaultValue `""`
   */
  yhoverformat?: string;
  /**
   * d3 number or date format of z values in hover labels. Default: the axis format.
   *
   * @defaultValue `""`
   */
  zhoverformat?: string;
};

