/**
 * A scalar field on a 3D grid drawn as a volume: stacked translucent isosurfaces (as Plotly) or GPU ray marching, with an opacity scale, colored by value.
 */
export type VolumeTrace = CommonTraceAttributes & {
  /**
   * Trace type.
   */
  type: 'volume';
  /**
   * The 3D scene this trace is drawn in: `'scene'` (`layout.scene`), `'scene2'` (`layout.scene2`), ….
   *
   * @defaultValue `"scene"`
   */
  scene?: 'scene' | `scene${number}`;
  /**
   * X coordinate of every grid point (numbers, dates or categories): `x`, `y`, `z` and `value` are flattened columns of a rectilinear grid, one entry per point, the axes nested in any order.
   */
  x?: DataColumn;
  /**
   * Y coordinate of every grid point (numbers, dates or categories): `x`, `y`, `z` and `value` are flattened columns of a rectilinear grid, one entry per point, the axes nested in any order.
   */
  y?: DataColumn;
  /**
   * Z coordinate of every grid point (numbers, dates or categories): `x`, `y`, `z` and `value` are flattened columns of a rectilinear grid, one entry per point, the axes nested in any order.
   */
  z?: DataColumn;
  /**
   * The value at every grid point (numbers): the field whose level surfaces are drawn and which the colorscale maps.
   */
  value?: DataColumn;
  /**
   * Lower end of the value range drawn. Default: the smallest value.
   */
  isomin?: number;
  /**
   * Upper end of the value range drawn. Default: the largest value.
   */
  isomax?: number;
  /**
   * The isosurfaces.
   */
  surface?: VolumeTraceSurface;
  /**
   * The space frame.
   */
  spaceframe?: VolumeTraceSpaceframe;
  /**
   * Slices through the grid.
   */
  slices?: VolumeTraceSlices;
  /**
   * Caps on the grid's boundary.
   */
  caps?: VolumeTraceCaps;
  /**
   * Text per grid point, shown in hover labels (after the value) and as `%{text}` in templates.
   *
   * @defaultValue `""`
   */
  text?: PerPoint<string | number>;
  /**
   * Colorscale for numeric `value` values: a name (`'Viridis'`, `'RdBu'`, …), a list of colors, or `[position, color]` stops from 0 to 1.
   */
  colorscale?: ColorScale | readonly string[] | readonly (readonly (number | string)[])[];
  /**
   * Pick the colorscale from the sign of the color domain (Reds for ≥ 0, Blues for ≤ 0, RdBu across 0). Defaults to true unless `colorscale` is given.
   */
  autocolorscale?: boolean;
  /**
   * Reverse the colorscale (the lowest value gets the last color).
   *
   * @defaultValue `false`
   */
  reversescale?: boolean;
  /**
   * Compute the color domain from the numeric `value` values. Defaults to false when both `cmin` and `cmax` are given.
   */
  cauto?: boolean;
  /**
   * Value mapped to the first colorscale color (with `cmax`; turns `cauto` off).
   */
  cmin?: number;
  /**
   * Value mapped to the last colorscale color (with `cmin`; turns `cauto` off).
   */
  cmax?: number;
  /**
   * With `cauto`, widen the automatic domain so it is symmetric around this value (diverging data).
   */
  cmid?: number;
  /**
   * Show a colorbar for this colorscale (drawn by the colorbar component, plan E5.3).
   *
   * @defaultValue `true`
   */
  showscale?: boolean;
  /**
   * The colorbar of this colorscale (plan E5.3).
   */
  colorbar?: Colorbar;
  /**
   * Share a colorscale and domain with other traces through `layout.coloraxis` (`'coloraxis'`, `'coloraxis2'`, …). Overrides this container's colorscale attributes.
   *
   * @defaultValue `"coloraxis"`
   */
  coloraxis?: 'coloraxis' | `coloraxis${number}`;
  /**
   * Flat shading: one normal per triangle (the default, as in Plotly: the extracted triangles share no vertices, so smooth shading looks the same).
   *
   * @defaultValue `true`
   */
  flatshading?: boolean;
  /**
   * Plotly's lighting model: coefficients of the ambient, diffuse and specular light. With `scene.lighting`, they scale the scene's lights.
   */
  lighting?: VolumeTraceLighting;
  /**
   * Position of the light (Plotly's model, without `scene.lighting`), in clip space: it moves with the view.
   */
  lightposition?: VolumeTraceLightposition;
  /**
   * The material of the surface (Holochart extension). Plotly figures keep the default, `plotly`.
   */
  material?: Bar3dTraceMaterial;
  /**
   * d3 number format of x values in hover labels. Default: the scene's x axis format.
   *
   * @defaultValue `""`
   */
  xhoverformat?: string;
  /**
   * d3 number format of y values in hover labels. Default: the scene's y axis format.
   *
   * @defaultValue `""`
   */
  yhoverformat?: string;
  /**
   * d3 number format of z values in hover labels. Default: the scene's z axis format.
   *
   * @defaultValue `""`
   */
  zhoverformat?: string;
  /**
   * d3 number format of value values in hover labels. Default: the value with hover precision.
   *
   * @defaultValue `""`
   */
  valuehoverformat?: string;
  /**
   * Opacity by value, like a colorscale: `[[0, 0.1], [0.5, 1], [1, 0.4]]` (positions 0–1 of the color domain, opacities 0–1), or `'max'` (the highest values opaque, the lowest faded to 0.1), `'min'` (the reverse), `'extremes'` (both ends opaque, the middle faded) or `'uniform'` (the default: `opacity` everywhere). Multiplies `opacity`.
   */
  opacityscale?: unknown;
  /**
   * How the volume is drawn (Holochart extension). `'isosurfaces'`: Plotly's stacked translucent isosurfaces (`surface.count` of them), with caps, slices and the space frame. `'raymarch'`: GPU ray marching through the grid (a 3D texture), every value in `[isomin, isomax]` drawn with the colorscale and `opacity` · `opacityscale` (the opacity of one grid cell's thickness); `surface`, `caps`, `slices` and `spaceframe` don't apply.
   *
   * @defaultValue `"isosurfaces"`
   */
  render?: 'isosurfaces' | 'raymarch';
  /**
   * Ray-marching options (`render: 'raymarch'`).
   */
  raymarch?: VolumeTraceRaymarch;
};

/**
 * The isosurfaces.
 */
export interface VolumeTraceSurface {
  /**
   * Draw the isosurfaces between `isomin` and `isomax`.
   *
   * @defaultValue `true`
   */
  show?: boolean;
  /**
   * Number of isosurfaces, evenly spread from `isomin` to `isomax` (2: just those two; 1: the middle value).
   *
   * Minimum: 1
   *
   * @defaultValue `2`
   */
  count?: number;
  /**
   * Share of each surface triangle drawn: below 1 leaves a hole in each triangle (a lattice), 0 hides the surfaces.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
  /**
   * Which parts of the surfaces are drawn: every grid cell is cut into five tetrahedra (`A`–`D` at four corners, `E` in the middle); `'all'`, a combination such as `'A+B'`, or `'odd'` / `'even'` (only the cells whose `i + j + k` is odd / even: a checkerboard).
   *
   * @defaultValue `"all"`
   */
  pattern?:
    | 'A'
    | 'B'
    | 'C'
    | 'D'
    | 'E'
    | `${'A' | 'B' | 'C' | 'D' | 'E'}+${string}`
    | 'all'
    | 'odd'
    | 'even';
}

/**
 * The space frame.
 */
export interface VolumeTraceSpaceframe {
  /**
   * Draw the space frame: the faces of the central tetrahedron of every grid cell inside `[isomin, isomax]`, useful with open surfaces or caps.
   *
   * @defaultValue `false`
   */
  show?: boolean;
  /**
   * Share of each space-frame triangle drawn (default 1).
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * Slices through the grid.
 */
export interface VolumeTraceSlices {
  /**
   * Slices of constant x.
   */
  x?: VolumeTraceSlicesX;
  /**
   * Slices of constant y.
   */
  y?: VolumeTraceSlicesY;
  /**
   * Slices of constant z.
   */
  z?: VolumeTraceSlicesZ;
}

/**
 * Slices of constant x.
 */
export interface VolumeTraceSlicesX {
  /**
   * Draw slices: planes of constant x through the grid, where the values are in `[isomin, isomax]`.
   *
   * @defaultValue `false`
   */
  show?: boolean;
  /**
   * x positions of the slices (between grid planes: interpolated). Default: every inner grid plane of x.
   */
  locations?: DataColumn;
  /**
   * Share of each slice triangle drawn: below 1 leaves a hole in each triangle (a lattice), 0 hides the slices.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * Slices of constant y.
 */
export interface VolumeTraceSlicesY {
  /**
   * Draw slices: planes of constant y through the grid, where the values are in `[isomin, isomax]`.
   *
   * @defaultValue `false`
   */
  show?: boolean;
  /**
   * y positions of the slices (between grid planes: interpolated). Default: every inner grid plane of y.
   */
  locations?: DataColumn;
  /**
   * Share of each slice triangle drawn: below 1 leaves a hole in each triangle (a lattice), 0 hides the slices.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * Slices of constant z.
 */
export interface VolumeTraceSlicesZ {
  /**
   * Draw slices: planes of constant z through the grid, where the values are in `[isomin, isomax]`.
   *
   * @defaultValue `false`
   */
  show?: boolean;
  /**
   * z positions of the slices (between grid planes: interpolated). Default: every inner grid plane of z.
   */
  locations?: DataColumn;
  /**
   * Share of each slice triangle drawn: below 1 leaves a hole in each triangle (a lattice), 0 hides the slices.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * Caps on the grid's boundary.
 */
export interface VolumeTraceCaps {
  /**
   * The caps at the grid's first and last x.
   */
  x?: VolumeTraceCapsX;
  /**
   * The caps at the grid's first and last y.
   */
  y?: VolumeTraceCapsY;
  /**
   * The caps at the grid's first and last z.
   */
  z?: VolumeTraceCapsZ;
}

/**
 * The caps at the grid's first and last x.
 */
export interface VolumeTraceCapsX {
  /**
   * Draw the caps: the grid's two boundary faces of constant x where the values are in `[isomin, isomax]`, which close the surfaces cut by the grid's edge.
   *
   * @defaultValue `true`
   */
  show?: boolean;
  /**
   * Share of each cap triangle drawn: below 1 leaves a hole in each triangle, 0 hides the caps.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * The caps at the grid's first and last y.
 */
export interface VolumeTraceCapsY {
  /**
   * Draw the caps: the grid's two boundary faces of constant y where the values are in `[isomin, isomax]`, which close the surfaces cut by the grid's edge.
   *
   * @defaultValue `true`
   */
  show?: boolean;
  /**
   * Share of each cap triangle drawn: below 1 leaves a hole in each triangle, 0 hides the caps.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * The caps at the grid's first and last z.
 */
export interface VolumeTraceCapsZ {
  /**
   * Draw the caps: the grid's two boundary faces of constant z where the values are in `[isomin, isomax]`, which close the surfaces cut by the grid's edge.
   *
   * @defaultValue `true`
   */
  show?: boolean;
  /**
   * Share of each cap triangle drawn: below 1 leaves a hole in each triangle, 0 hides the caps.
   *
   * Range: 0 – 1
   *
   * @defaultValue `1`
   */
  fill?: number;
}

/**
 * Plotly's lighting model: coefficients of the ambient, diffuse and specular light. With `scene.lighting`, they scale the scene's lights.
 */
export interface VolumeTraceLighting {
  /**
   * Ambient light: the share of the color shown whatever the direction of the light.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.8`
   */
  ambient?: number;
  /**
   * Diffuse light: the share of the color lit by the light (Lambert).
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.8`
   */
  diffuse?: number;
  /**
   * Specular highlights: the light reflected toward the eye.
   *
   * Range: 0 – 2
   *
   * @defaultValue `0.05`
   */
  specular?: number;
  /**
   * Roughness of the surface: the spread of the specular highlights.
   *
   * Range: 0 – 1
   *
   * @defaultValue `0.5`
   */
  roughness?: number;
  /**
   * Fresnel reflection: how much more light surfaces reflect at grazing angles.
   *
   * Range: 0 – 5
   *
   * @defaultValue `0.2`
   */
  fresnel?: number;
  /**
   * Vertex normals ignore triangle normals shorter than this (tiny triangles do not skew smooth shading).
   *
   * Range: 0 – 1
   *
   * @defaultValue `1e-12`
   */
  vertexnormalsepsilon?: number;
  /**
   * Triangles whose normal is shorter than this get no normal in flat shading (degenerate triangles).
   *
   * Range: 0 – 1
   *
   * @defaultValue `0`
   */
  facenormalsepsilon?: number;
}

/**
 * Position of the light (Plotly's model, without `scene.lighting`), in clip space: it moves with the view.
 */
export interface VolumeTraceLightposition {
  /**
   * x of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `100000`
   */
  x?: number;
  /**
   * y of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `100000`
   */
  y?: number;
  /**
   * z of the light, in clip space (moves with the view; ±1 is the edge of the view, 1e5 far away).
   *
   * Range: -100000 – 100000
   *
   * @defaultValue `0`
   */
  z?: number;
}

/**
 * Ray-marching options (`render: 'raymarch'`).
 */
export interface VolumeTraceRaymarch {
  /**
   * Sample spacing along the rays, in grid cells: smaller is finer and slower (the opacity per cell stays the same).
   *
   * Range: 0.05 – 4
   *
   * @defaultValue `0.5`
   */
  step?: number;
  /**
   * Shade by the value gradient: a light at the camera, with the trace's `lighting.ambient` and `lighting.diffuse` (six more samples per step).
   *
   * @defaultValue `false`
   */
  shading?: boolean;
}

/**
 * Any trace of `@mk7s/holochart-traces-3d`, discriminated on `type`. Type a partial bundle's figures with it: `FigureInput<Traces3d>`.
 */
export type Traces3d =
  | Bar3dTrace
  | ConeTrace
  | IsosurfaceTrace
  | Mesh3dTrace
  | Scatter3dTrace
  | StreamtubeTrace
  | SurfaceTrace
  | VolumeTrace;
